object Customers : Table("customer") {
    val id = long("id")
    val name = varchar("name", 64)
    override val primaryKey = PrimaryKey(id)
}

class CustomerDao(private val db: Database) {
    fun find(id: Long): Customer? = transaction(db) {
        Customers.selectAll().where { Customers.id eq id }
            .singleOrNull()
            ?.let { Customer(it[Customers.id], it[Customers.name]) }  // data class, not ResultRow
    }
}
